<?php
declare(strict_types=1);
namespace AM2050\Controllers;
use AM2050\Core\Request; use AM2050\Core\Response; use AM2050\Middleware\AuthMiddleware; use AM2050\Middleware\RoleMiddleware; use AM2050\Services\GeographyService;
final class GeographyController { public function __construct(private readonly AuthMiddleware $auth,private readonly GeographyService $service){} public function list(Request $request,array $params):never{$this->auth->require($request);Response::success($this->service->list($params['resource'],$request->query));} private function admin(Request $request):array{$actor=$this->auth->require($request);RoleMiddleware::require($actor,'super_admin');return$actor;} public function create(Request $request,array $params):never{$actor=$this->admin($request);Response::success($this->service->create($actor,$params['resource'],$request->body()),201);} public function update(Request $request,array $params):never{$actor=$this->admin($request);Response::success($this->service->update($actor,$params['resource'],$params['id'],$request->body()));} public function deactivate(Request $request,array $params):never{$actor=$this->admin($request);Response::success($this->service->deactivate($actor,$params['resource'],$params['id']));} }
